mapper.update:
UPDATE scene_videos
SET is_active = 0
WHERE scene_id = #{sceneId}

mapper.select:
SELECT id, scene_id, asset_id, thumbnail_asset_id, merge_signature, status, duration_ms, thumbnail_url, is_active, created_at, updated_at
FROM scene_videos
WHERE id = #{sceneVideoId}

SELECT COUNT(*)
FROM scene_videos
WHERE scene_id = #{sceneId}

SELECT id, scene_id, asset_id, thumbnail_asset_id, merge_signature, status, duration_ms, thumbnail_url, is_active, created_at, updated_at
FROM scene_videos
WHERE scene_id = #{sceneId}
ORDER BY created_at DESC, id DESC
LIMIT #{limit} OFFSET #{offset}

mapper.delete:
DELETE FROM scene_videos
WHERE id = #{sceneVideoId}
  AND scene_id = #{sceneId}
  AND is_active = 0
